        letter-spacing: 5px;
        margin-top: 4px;
    }
    .regua {
        border-top: 3px solid #000;
        border-bottom: 1px solid #000;
        height: 4px;
        margin: 12px 0 4px 0;
    }
    .barra {
        display: flex;
        justify-content: space-between;
        font-size: 15px;
