        letter-spacing: 1px;
        padding: 4px 6px;
    }
    .regua2 {
        border-top: 1px solid #000;
        border-bottom: 3px solid #000;
        height: 4px;
        margin: 4px 0 14px 0;
    }
    .colunas {
        column-count: 3;
        column-gap: 26px;
        column-rule: 1px solid #000;
        text-align: justify;
        font-size: 13px;
        line-height: 1.25;
    }
    .colunas p {
        margin: 0;
        text-indent: 18px;
    }
    h2.secao {
        text-align: center;
        font-size: 22px;
